function getTimeStr(sleep = 0) {
  let time = new Date()
  time.setTime(time.getTime() + 86400000 * (sleep))
  let year = time.getFullYear()
  let month: number | string = time.getMonth() + 1
  if (month < 10) {
    month = '0' + month
  }
  let day: number | string = time.getDate()
  if (day < 10) {
    day = '0' + day
  }
  return year + '-' + month + '-' + day
}

