<script setup lang="ts">
import { ref, onMounted } from 'vue'
import Page from '@/components/Page.vue'
import request from '@/plugin/request'
import Loading from '@/plugin/loading'
import toast from '@/plugin/toast'

// 订单状态类型
interface OrderItem {
  id: number
  orderId: string
  outOrderID: string
  address: string;
  ctime: string;
  name: string;
  price: number;
  status?: number | string;
}

// 响应式数据
const orderList = ref<OrderItem[]>([])
const loading = ref<boolean>(true)
const showDetail = ref<boolean>(false)
type stateType = 0 | 1 | -1;
const selectedOrder = ref<OrderItem & {
  order_status: stateType
  description: string;
  out_order_no: string;
  // 快递信息
  courierCompany?: string;
  deliveryTime?: string;
  logistics?: {
    code: 400 | 200,
    msg: string,
    data?: {
      list: Array<{
        time: string,
        status: string
      }>
    },
  }
} | null>(null)
const currentTab = ref<string>('all')

// 订单筛选标签
// const orderTabs = [
//   { key: 'all', name: '全部订单' },
//   { key: 'pending', name: '待支付' },
//   { key: 'paid', name: '已支付' },
//   { key: 'shipped', name: '已发货' },
//   { key: 'completed', name: '已完成' },
//   { key: 'cancelled', name: '已取消' }
// ]

// 切换订单筛选标签
const switchTab = (tab: string) => {
  currentTab.value = tab
  loadOrders()
}

// 获取订单列表
const loadOrders = async () => {
  loading.value = true
  try {
    const res = await request.get('/studying/print/myOrderList')
    // 模拟订单数据，实际应从API获取
    const mockOrders: OrderItem[] = res as any;

    orderList.value = mockOrders

    // // 根据当前筛选标签过滤订单
    // if (currentTab.value === 'all') {
    //   orderList.value = mockOrders
    // } else {
    //   orderList.value = mockOrders.filter(order => order.status === currentTab.value)
    // }
  } catch (error) {
    console.error('获取订单列表失败:', error)
  } finally {
    loading.value = false
  }
}

// 获取订单状态文本
const getOrderStatusText = (status: stateType) => {
  const statusMap: Record<stateType, string> = {
    0: '订单制作中',
    1: '已发货',
    [-1]: '已取消',
  }
  return statusMap[status] || '未知状态'
}

// 获取订单状态样式类
const getStatusClass = (status: stateType) => {
  return `status-${status}`
}

// 根据订单数据获取展示用的状态文本（列表页用）
const getDisplayStatusText = (order: OrderItem): string => {
  const s = order.status
  if (s === 1 || s === '1' || s === 'completed' || s === '已完成') return '已完成'
  if (s === 0 || s === '0' || s === 'pending' || s === '待支付') return '待支付'
  if (s === -1 || s === '-1' || s === 'cancelled' || s === '已取消') return '已取消'
  return '待支付'
}

// 根据订单数据获取状态标签样式类（列表页用）
const getStatusTagClass = (order: OrderItem): string => {
  const s = order.status
  if (s === 1 || s === '1' || s === 'completed' || s === '已完成') return 'tag-done'
  if (s === -1 || s === '-1' || s === 'cancelled' || s === '已取消') return 'tag-cancel'
  return 'tag-pending'
}

// 查看订单详情
const viewOrderDetail = async (order: OrderItem) => {
  const loading = Loading();
  const res: any = await request.get('/studying/print/orderInfo/' + order.id)
  console.log('222222', res)
  if (res.code === 200) {
    loading.destory()
    showDetail.value = true;
    selectedOrder.value = {
      ...order,
      order_status: res.data.status,
      logistics: res.logistics,
      ...res.data
    };
  } else {
    loading.destory()
    toast({
      'message': res.error,
      'duration': 3000
    })
  }
}

// 支付订单
const payOrder = (order: OrderItem) => {
  console.log('支付订单:', order)
  // 这里应该调用支付接口
  alert(`正在支付订单 ${order.outOrderID}`)
}

// 删除订单
const deleteOrder = (order: OrderItem) => {
  console.log('删除订单:', order)
  // 这里应该调用删除订单接口
  if (confirm(`确定要删除订单 ${order.outOrderID} 吗？`)) {
    orderList.value = orderList.value.filter(item => item.id !== order.id)
  }
}

// 组件挂载时加载订单数据
onMounted(() => {
  loadOrders()
})
</script>

